const aiOutput = $input.first().json.output;
let petTipData;

try {
  // Try to parse the AI response as JSON
  petTipData = JSON.parse(aiOutput);
} catch (error) {
  // Fallback if AI doesn't return valid JSON
  petTipData = {
    tip: aiOutput,
    hashtags: ["#PetCare", "#VetTips", "#HealthyPets", "#PetClinic"],
    callToAction: "What's your favorite pet care tip? Share below!",
    petType: "General"
  };
}

// Ensure hashtags is an array
if (!Array.isArray(petTipData.hashtags)) {
  petTipData.hashtags = ["#PetCare", "#VetTips", "#HealthyPets", "#PetClinic"];
}

// Add clinic-specific hashtags
const clinicHashtags = ["#{{CLINIC_HASHTAG}}", "#PetTipTuesday", "#VeterinaryAdvice"];
petTipData.hashtags = [...petTipData.hashtags, ...clinicHashtags];

// Create the social media post
const socialMediaPost = `🐾 Pet Tip Tuesday! 🐾\n\n${petTipData.tip}\n\n${petTipData.callToAction}\n\n${petTipData.hashtags.join(' ')}\n\n📍 {{CLINIC_NAME}} - Your trusted partner in pet health!\n📞 {{BUSINESS_PHONE_NUMBER}} | 🌐 {{CLINIC_WEBSITE}}`;

return [{
  json: {
    postContent: socialMediaPost,
    tip: petTipData.tip,
    hashtags: petTipData.hashtags,
    callToAction: petTipData.callToAction,
    petType: petTipData.petType,
    timestamp: new Date().toISOString(),
    clinic: "{{CLINIC_NAME}}"
  }
}];
